  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C06"],
      "claim": "The closest analog, [18F]CBX, showed only very low brain uptake on PET with a tissue-to-plasma SUV ratio below 1, indicating inadequate BBB penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "A moderately similar compound showed negligible rat brain concentrations (3–5% of plasma) after oral administration, supporting poor CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "A less similar analog, [11C]MPDX, was widely distributed in monkey brain and readily penetrated the BBB, providing contradictory evidence for possible CNS access.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The very high similarity of the query to a direct PET probe with minimal brain uptake strongly supports inadequate CNS access. Other permeable analogs are less similar and do not override this closest, condition-matched evidence.",
  "evidence_gaps": [
    "No direct in vivo brain exposure data for the exact query molecule are provided.",
    "Most positive BBB-penetration evidence comes from structurally more distant molecules."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

